711	\section{Doob-Meyer decomposition}
712	
713	
714	
715	For uniqueness of Doob-Meyer Decomposition we will need theorem
716	\ref{thm:IsLocalMartingale.eq_zero_of_predictable_finiteVariation}.
717	
718	We now start the construction for the existence part.
719	
720	
721	\begin{definition}[Dyadics]\label{def:dyadics}
722	For $T>0$, let $\mathcal{D}_n^T = \left\lbrace \frac{k}{2^n}T \mid k=0,\cdots 2^n\right\rbrace$ be the set of dyadics at scale $n$ and let $\mathcal{D}^T=\bigcup_{n\in\mathbb{N}}\mathcal{D}_n^T$ be the set of all dyadics of $[0,T]$.
723	\end{definition}
724	
725	Let $S : [0,T] \to \Omega \to \mathbb{R}$ be a cadlag submartingale of class D on $[0,T]$.
726	
727	
728	
729	\begin{definition}[S, A, M]\label{def:SAM}
730	  \uses{def:dyadics, def:predictablePart}
731	For $n \in \mathbb{N}$, the restriction of $S$ to $\mathcal{D}_n^T$ is a discrete time submartingale $S^n : \mathbb{N} \to \Omega \to \mathbb{R}$ with respect to the filtration $\mathcal{F}^n_k = \mathcal{F}_{k2^{-n}T}$, with $S^n_k = S_{k2^{-n}T}$ (and constant equal to $S_T$ for $k > 2^n$; similarly for the filtration), and we can apply the construction of the previous section to it.
732	Let $A^n$ and $M^n$ be the predictable and martingale parts of $S^n$.
733	\end{definition}
734	
735	
736	\begin{lemma}\label{lem:A_uniform_integrable}
737	  \uses{def:SAM}
738	  The sequence $(A^n_{2^n})_{n\in\mathbb{N}}$ is uniformly integrable (bounded in $L^1$ norm).
739	\end{lemma}
740	
741	Remark: $A^n_{2^n}$ is the predictable part of $S$ at time $T$ for the discrete time filtration given by the dyadics at scale $n$.
742	
743	\begin{proof}
744	  \uses{lem:uniformIntegrable_predictablePart_aux4, lem:uniformIntegrable_predictablePart_aux5, def:classD, lem:predictablePart_add, lem:martingalePart_add, lem:Martingale.predictablePart_eq_zero}
745	WLOG $S^n_{2^n} = S_T=0$ and $S_t\leq 0$ (else consider $S_t-\mathbb{E}\left[S_T\vert\mathcal{F}_{t}\right]$).
746	
747	We write $\tau_n(c)$ for the hitting time $\tau^T_{A^n_{k+1}>c}$.
748	
749	By Lemma~\ref{lem:uniformIntegrable_predictablePart_aux4},
750	$$
751	\int_{(A^n_{2^n}>c)} A^n_{2^n} dP
752	\le -2 \int_{\tau_n(c/2)< 2^n} S^n_{\tau_n(c/2)} dP - \int_{\tau_n(c) < 2^n} S^n_{\tau_n(c)} dP.
753	$$
754	On the other hand, by Lemma~\ref{lem:uniformIntegrable_predictablePart_aux5},
755	$$
756	P(\tau_n(c)<2^n) \le -\frac{\mathbb{E}[S_0]}{c}
757	$$
758	which goes to $0$ uniformly in $n$ as $c$ goes to infinity.
759	
760	The integrals in the upper bound on $\int_{(A^n_{2^n}>c)} A^n_{2^n} dP$ are integrals of uniformly integrable random variables (by the class D assumption) over sets whose probability goes to zero uniformly.
761	Therefore, these integrals go to zero uniformly in $n$ as $c$ goes to infinity.
762	
763	This implies that $\int_{(A^n_{2^n}>c)} A^n_{2^n} dP$ goes to 0 uniformly in $n$ as $c \to +\infty$.
764	Hence, the $L^1$ norm is uniformly bounded.
765	\end{proof}
766	
767	
768	\begin{lemma}\label{lem:M_uniform_integrable}
769	  \uses{def:SAM}
770	  The sequence $(M^n_{2^n})_{n\in\mathbb{N}}$ is uniformly integrable (bounded in $L^1$ norm).
771	\end{lemma}
772	
773	\begin{proof}
774	  \uses{lem:A_uniform_integrable, lem:ClassD.uniformIntegrable}
775	$M^n_{2^n} = S_{2^n} - A^n_{2^n}$, also $S$ is of class $D$ hence uniformly integrable and $A^n_{2^n}$ is uniformly integrable by Lemma~\ref{lem:A_uniform_integrable}.
776	\end{proof}
777	
778	
779	\begin{lemma}\label{lem:M_n_cadlag_mg}
780	  \uses{def:SAM}
781	The martingale on $[0, T]$ defined by $t \mapsto \mathbb{E}[M^n_{2^n}\vert\mathcal{F}_t]$ admits a modification which is a cadlag martingale.
782	\end{lemma}
783	
784	\begin{proof}
785	  \uses{thm:Martingale.exists_cadlag_modification}
786	By theorem \ref{thm:Martingale.exists_cadlag_modification}
787	\end{proof}
788	
789	
790	\begin{definition}\label{def:barM}
791	  \uses{lem:M_n_cadlag_mg}
792	For $t\in[0,T]$ let $\overline{M}^n_t$ be the cadlag modification of $t \mapsto \mathbb{E}[M^n_{2^n} \mid \mathcal{F}_t]$ from lemma \ref{lem:M_n_cadlag_mg}.
793	\end{definition}
794	
795	
796	\begin{lemma}\label{lem:M_cal_converges_L1}
797	  \uses{def:barM}
798	  There exists an $M : \Omega \to \mathbb{R}$ and convex weights $\lambda^n_n,\cdots,\lambda^n_{N_n}$ such that
799	  $\mathcal{M}^n_T\stackrel{L^1}{\rightarrow}M$, where $\mathcal{M}^n_T := \lambda^n_n \overline{M}^n_T+ \cdots + \lambda^n_{N_n} \overline{M}^{N_n}_T$~.
800	\end{lemma}
801	
802	\begin{proof}
803	  \uses{lem:M_uniform_integrable,lem:komlos}
804	  By lemma \ref{lem:M_uniform_integrable} $(M^n_T)_{n\in\mathbb{N}}$ is uniformly bounded in $L^1$, thus by lemma \ref{lem:komlos} there are convex weights $\lambda^n_n,\cdots,\lambda^n_{N_n}$ such that
805	  $\mathcal{M}^n_T\stackrel{L^1}{\rightarrow}M$, where $\mathcal{M}^n_T := \lambda^n_n \overline{M}^n_T+ \cdots + \lambda^n_{N_n} \overline{M}^{N_n}_T$~.
806	\end{proof}
807	
808	
809	\begin{definition}\label{def:calM}
810	  \uses{lem:M_cal_converges_L1, def:barM}
811	For $t\in[0,T]$ let $\mathcal{M}^n_t=\lambda^n_n \overline{M}^n_t+\cdots +\lambda^n_{N_n} \overline{M}^{N_n}_t$ be the convex combination of the $\overline{M}^n_t$'s with the weights from Lemma~\ref{lem:M_cal_converges_L1} and let $M$ be the limit of $\mathcal{M}^n_T$ from the same lemma.
812	\end{definition}
