815	\begin{lemma}\label{lem:M_cal_cadlag}
816	  \uses{def:calM}
817	  $\mathcal{M}^n$ is cadlag.
818	\end{lemma}
819	
820	\begin{proof}
821	  \uses{lem:M_n_cadlag_mg,lem:M_cal_converges_L1}
822	  By construction and \ref{lem:M_n_cadlag_mg}
823	\end{proof}
