839	By Jensen's inequality, the tower lemma and lemma \ref{lem:M_cal_converges_L1}
840	\begin{gather}\nonumber
841	  \mathbb{E}[|\mathcal{M}^n_t-M_t|]
842	  = \mathbb{E}[|\mathbb{E}[\mathcal{M}^n_T-M\vert\mathcal{F}_t]|]
843	  \le \mathbb{E}[|\mathcal{M}^n_T-M|]\rightarrow0 \: ,
844	  \\
845	  \Rightarrow \mathcal{M}^n_t\stackrel{L^1}{\rightarrow} M_t,\quad \forall t\in[0,T].\label{equation_DM_e7}
846	\end{gather}
847	\end{proof}
